code_sketch:
struct Money { long long minor; std::string currency; };
struct Order { long long id; Money total; };

Order load(const row& r) {
  auto [minor, currency] = std::tuple{
      r.get<long long>("total_minor"), r.get<std::string>("total_currency")};
  return Order{r.get<long long>("id"), Money{minor, currency}};
}

void bind(statement& s, const Order& o) {
  s.bind(2, o.total.minor).bind(3, o.total.currency);
}

